(window.webpackJsonp=window.webpackJsonp||[]).push([[74],{444:function(v,_,p){"use strict";p.r(_);var t=p(11),e=Object(t.a)({},(function(){var v=this,_=v._self._c;return _("ContentSlotsDistributor",{attrs:{"slot-key":v.$parent.slotKey}},[_("h3",{attrs:{id:"原文"}},[_("a",{staticClass:"header-anchor",attrs:{href:"#原文"}},[v._v("#")]),v._v(" 原文")]),v._v(" "),_("p",[_("font",{attrs:{color:"#be5656",size:"5px"}},[_("center",[v._v("第一篇")])],1)],1),v._v(" "),_("p",[v._v("“捭”即开启，“阖”即闭藏，所谓“捭阖”，就是大开大合，大启大闭。鬼谷子将“捭阖”之道与中国古代源远流长的阴阳学说融会贯通，并将之运用于纵横游说的说术言略中，使之成为战国策士们立身处世、说诸侯、干人主、掌机变、握形势的总原则，进而衍生出那个时代的纵横风云。因此，作为《鬼谷子》一书开宗明义的第一篇，《捭阖》无疑具有提纲挈领、一以贯之的重要地位。")]),v._v(" "),_("p",[_("strong",[v._v("一")])]),v._v(" "),_("p",[v._v("奥若稽古[1]，圣人之在天地间也[2]，为众生之先[3]。观阴阳之开阖以命物[4]，知存亡之门户[5]，筹策万类之终始，达人心之理，见变化之朕焉[6]，而守司其门户[7]。故圣人之在天下也，自古及今，其道一也[8]。变化无穷，各有所归[9]。或阴或阳，或柔或刚，或开或闭，或弛或张。是故圣人一守司其门户，审察其所先后，度权量能[10]，校其伎巧短长。")]),v._v(" "),_("br"),v._v(" "),_("Badge",{attrs:{text:"注释",type:"warning"}}),v._v(" "),_("p",[v._v("[1]粤：句首语助词，表庄重。若：沿着。此指上溯。稽：考察。")]),v._v(" "),_("p",[v._v("[2]圣人：《鬼谷子》中所言“圣人”有两种含义，一种指古代有所贡献、有所创见的大智大勇之士，一种指当代精于纵横权术的游说辩士，与儒家所言“圣人”有别。此句中的“圣人”当指前一种。")]),v._v(" "),_("p",[v._v("[3]众生：泛指万物生灵。此处特指民众。先：先知先觉，指能够预测事物发展动向，掌握事物发展规律的人。")]),v._v(" "),_("p",[v._v("[4]命物：意指抓住事物本质，表述事物名称和性质。")]),v._v(" "),_("p",[v._v("[5]存亡之门户：指世上万事万物生成、发展灭亡的关键所在。")]),v._v(" "),_("p",[v._v("[6]朕：指可以观测到的事物发展形迹、征兆。")]),v._v(" "),_("p",[v._v("[7]守司：把握，掌握。")]),v._v(" "),_("p",[v._v("[8]其道一也：即言自古至今，圣人的做法、目的都是一样的。")]),v._v(" "),_("p",[v._v("[9]各有所归：即言事物的发展变化皆有一定规律可循。")]),v._v(" "),_("p",[v._v("[10]权：权变。此指事物可以变化、可让人施术变动其发展方向的成分。能：能力。此指事物保持自己的不变性从而按自己的固定轨迹运行的能力。")]),v._v(" "),_("Badge",{attrs:{text:"译文",type:"warning"}}),v._v(" "),_("p",[v._v("先让我们来考察一下历史吧。古代那些大智大勇的圣者生活在人世间，之所以成为芸芸众生先知先觉的导师，是因为他们能够通过对世界上万事万物阴阳、分合变化的观测，揭示它们的本质属性而给它们立一个确定的名号，并洞晓其生成、发展、灭亡的关键所在，追溯事物发展的历史过程，预测其结局，还能洞察世人的心理变化规律，及时发现世上事物、人事的发展征兆，从而把握其关键所在。所以，圣人在社会上立身处世，从古到今，其遵循的规律都是一样的。由此而论，世间事物虽然变化无穷、纷纭万端，但皆有其自身的本质特征与发展规律：或归于阴，或归于阳；或以柔为特征，或以刚为特征；或以开放为主导，或以闭藏为主导；或松弛不固，或紧张难入。因此，圣人在处理世间事务时，总是善于发现事物规律，把握事物关键，考察事物的发展过程，揣度、研究事物的可变性和不变性以及事物应变能力的强弱，因才而用、取长补短、有的放矢地处理问题。")]),v._v(" "),_("Badge",{attrs:{text:"阅读感悟",type:"warning"}}),v._v(" "),_("p",[v._v("善于观察事物存在状态，洞悉其展现和隐藏的部分。真实和防御，缺少和擅长，可以知人善用。")]),v._v(" "),_("p",[_("strong",[v._v("二")])]),v._v(" "),_("p",[v._v("夫贤、不肖，智、愚，勇、怯，仁、义，有差[1]，乃可捭，乃可阖；乃可进，乃可退；乃可贱，乃可贵，无为以牧之[2]。审定有无与其虚实，随其嗜欲以见其志意，微排其所言而捭反之[3]，以求其实，贵得其指[4]；阖而捭之，以求其利。或开而示之，或阖而闭之[5]。开而示之者，同其情也；阖而闭之者，异其诚也[6]。可与不可，审明其计谋，以原其同异。离合有守，先从其志[7]。即欲捭之贵周，即欲阖之贵密[8]。周密之贵微，而与道相追[9]。捭之者，料其情也；阖之者，结其诚也。皆见其权衡轻重，乃为之度数，圣人因而为之虑[10]。其不中权衡度数，圣人因而自为之虑[11]。故捭者，或捭而出之，或捭而内之[12]；阖者，或阖而取之，或阖而去之。")]),v._v(" "),_("br"),v._v(" "),_("Badge",{attrs:{text:"注释",type:"warning"}}),v._v(" "),_("p",[v._v("[1]有差：有差等，差别。")]),v._v(" "),_("p",[v._v("[2]无为：指无为之道。《鬼谷子》所说的“无为之道”与老庄的清静无为之道不同，这里指顺应自然之性而拨动之、因势而利导之的一种处世之道。牧：治理，处理。")]),v._v(" "),_("p",[v._v("[3]微：暗中。排：排察。")]),v._v(" "),_("p",[v._v("[4]指：同“旨”，旨意，主旨。")]),v._v(" "),_("p",[v._v("[5]示：启示，启发。此指启发对方让他敞开思想。闭：闭藏。此指使对方控制感情。")]),v._v(" "),_("p",[v._v("[6]异：与“同其情”之“同”为互词。同其情，即考察对方感情上与我们的同异点。异其诚，即考察对方诚意如何。")]),v._v(" "),_("p",[v._v("[7]离合有守：认识有差距。离合，原指二人相离或相逢，此指认识差距。守，原指各据一方，此指有距离。从：同“纵”，纵容，放纵。志：意愿，意志。")]),v._v(" "),_("p",[v._v("[8]贵：以……为贵，此处意为“首先要”、“关键是”。")]),v._v(" "),_("p",[v._v("[9]微：微暗，不露声色。道：此指阴阳之道，即变动阴阳、因势利导而处理事物的方法。追：相随，相合。")]),v._v(" "),_("p",[v._v("[10]权衡轻重：此指处理事情的谋略与措施。度数：度量，准则。")]),v._v(" "),_("p",[v._v("[11]自为之虑：此指自己另外谋划决策。")]),v._v(" "),_("p",[v._v("[12]内：同“纳”，接纳，吸收。")]),v._v(" "),_("Badge",{attrs:{text:"译文",type:"warning"}}),v._v(" "),_("p",[v._v("世人中有贤良与不肖者，有智识之士与愚黯之辈，有勇敢者和怯懦者；有仁人君子及苟且小人……总之，人们的品行和素质是千差万别的。所以，针对不同的人品素质，要采取不同的态度与措施。对某些人可以开导，对某些人可以压抑；对某些人可以擢用，对某些人可以黜退；可以让某些人富贵，可以使某些人贫贱。总归一句话，要顺应人们的自然品性去分别对待他们。要起用一个人，首先要审定其品质如何，摸清其真假虚实，顺从其嗜欲愿望，发掘其志向意图，并要暗中排察他的言语，或启导他，或适当地贬抑、质疑他，以探知其真情实意，以明了其性格主流。得知对方实际情况后应缄默不语以挑动对方畅所欲言，以便了解对方所言是否于己有利。要么开导他给他以启示，要么压抑他使他控制自己。开导启发他，是为了让他畅所欲言以考察他在感情上与我们有无距离；压抑控制他，是为了观察他的反应如何，借此了解他对我们的诚心大小。考察某人可用不可用，还要查明其谋略计划的优劣以及同自己谋略计划的差距大小。若同我们的谋略计划距离较大，先纵容他，让他照自己的意志去办（而我们则暗中谋划）。当然，这种谋划要周密。若要谋划周密，关键是行事要微暗、不露声色，这样做，就与阴阳之道暗合无隙了。对人使用捭阖之术，或开启引导他，估量出他的情志；或压抑控制他，摸准他的诚心。此外，还要知道他的谋略措施，圣人因之作出测度与分析，若其谋略措施得当，与我们距离较小，合乎我们的准则，我们就可以据此帮他完善谋略措施；若其谋略措施失当，与我们距离较大，不合我们的准则，我们只好舍弃不用，自己另谋良策。因此，对人使用捭阖之术时，或开导他帮他引出决策，或启发他吐露决策以便纳为己用；或抑制他以便于我们顺利起用，或拒斥他弃而不用。")]),v._v(" "),_("Badge",{attrs:{text:"阅读感悟",type:"warning"}}),v._v(" "),_("p",[v._v("顺应存在状态不强加改变，取其精华去其糟粕，用其所用。对内部结构灵活，心理和能力可塑性强的人加以帮助，对闭合的系统不加改变。用人，审视人的诚信，交换的可行性和合作的可信度，了解其渴望得到的，作为附加条件加以满足，帮助其实现志向意图，验证其言行一致性，适当表明自己的优势，从而了解其性情真意，和真实性格。得知其实际情况，让其多多表达，分析对方是否符合自己需求，其中利弊加以分析。有共同有益的部分加以肯定，不合适的地方进行规则约定。启发的部分有益的部分是为了考察合作的可能性，约定的地方是来判断合作的诚意。如果双方差距较大，不要去改变他人意向，顺其自身意向，自己另做谋划。")]),v._v(" "),_("p",[_("strong",[v._v("三")])]),v._v(" "),_("p",[v._v("捭阖者，天地之道[1]。捭阖者，以变动阴阳，四时开闭，以化万物。纵横、反出、反覆、反忤，必由此矣[2]。捭阖者，道之大化。说之变也，必豫审其变化，吉凶大命系焉[3]。口者，心之门户也；心者，神之主也。志意、喜欲、思虑、智谋，此皆由门户出入[4]，故关之以捭阖，制之以出入。捭之者，开也，言也，阳也；阖之者，闭也，默也，阴也。阴阳其和，终始其义[5]。故言长生、安乐、富贵、尊荣、显名、爱好、财利、得意、喜欲为阳，曰始[6]。故言死亡、忧患、贫贱、苦辱、弃损、亡利、失意、有害、刑戮、诛罚为阴，曰终[7]。诸言法阳之类者，皆曰始，言善以始其事；诸言法阴之类者，皆曰终，言恶以终其谋[8]。捭阖之道，以阴阳试之[9]。故与阳言者依崇高，与阴言者依卑小。以下求小，以高求大[10]。由此言之，无所不出，无所不入，无所不可[11]。可以说人，可以说家，可以说国，可以说天下[12]。为小无内，为大无外。")]),v._v(" "),_("br"),v._v(" "),_("Badge",{attrs:{text:"注释",type:"warning"}}),v._v(" "),_("p",[v._v("[1]天地之道：即阴阳之道。天为阳，地为阴。")]),v._v(" "),_("p",[v._v("[2]纵横、反出：即阴阳的具体表现。纵与横，反（返）与出，都是对立的事物，可用阴阳来涵括。反覆、反忤：亦为阴阳的具体表现。")]),v._v(" "),_("p",[v._v("[3]豫：同“预”，预先。吉凶：此指游说成功或失败。大命：此指游说目的。")]),v._v(" "),_("p",[v._v("[4]出入：此指表现、表述。")]),v._v(" "),_("p",[v._v("[5]阴阳其和，终始其义：终事始事的要义所在，是明了阴阳调和之理。")]),v._v(" "),_("p",[v._v("[6]故言长生……曰始：始为乾，乾为阳，故“始”“阳”并言。始即初始，出发点，引申为人生行动的目的所在。即言上述长生、安乐、富贵等事物都是人生所追求的东西。")]),v._v(" "),_("p",[v._v("[7]故言死亡……曰终：终为坤，坤为阴，故“终”“阴”并言。终：穷。穷急困窘，是人所不欲，是人生的忌讳。")]),v._v(" "),_("p",[v._v("[8]善：此指善言，善言为阳。恶：此指恶言，恶言为阴。")]),v._v(" "),_("p",[v._v("[9]阴阳：此指阴言和阳言。")]),v._v(" "),_("p",[v._v("[10]下：卑下的阴言。小：此指小人。高：崇高的阳言。大：此指君子。")]),v._v(" "),_("p",[v._v("[11]出：这里指被策士、说客们启发。入：这里指听从游说策士的话。")]),v._v(" "),_("p",[v._v("[12]家：这里指封有采邑的大夫。国：这里指据有一国的诸侯。")]),v._v(" "),_("Badge",{attrs:{text:"译文",type:"warning"}}),v._v(" "),_("p",[v._v("捭阖之术，以阴阳之道为主旨。捭阖，就是变动阴阳，用开闭之法构成四季轮回，使万物化生、万事兴亡交替。纵和横，返和出，反和覆，反与忤，皆为阴阳之道的具体表现，都可用阴阳变动来区别、说明它们。而使用捭阖之术使事物转化，正是阴阳之道的关键所在。游说过程中的每一变化，都出自捭阖之术，所以要预先审知捭阖之术的阴阳变化法则，这是游说能否成功、游说目的能否达到的关键所在。口，是表达内心思想的门户；而心灵，是人的精神世界的主宰。人的志向与意愿，喜好与欲求，思念和焦虑，智慧和谋略，都是由口这个门户出入从而表露出来的。所以，应该用捭阖之术来把守自己的口，用开闭之法来调控自己的言谈。使用捭术，就是让对方开口，让对方说话，这就是阳之道；使用阖术，就是让对方闭口，让对方沉默，这就是阴之道。懂得了阴阳之道的协调交替使用，就能够懂得“终”和“始”的意义了。所以，我们把长生、安乐、富贵、尊荣、显名、爱好、财利、得意、喜欲等归为阳类事物，称作人生向往；把死亡、忧患、贫贱、苦辱、弃损、亡利、失意、有害、刑戮、诛罚等归为阴类事物，称作人生忌讳。凡是那些遵循、效仿、涉及上述阳类事物的说辞，可以叫作“人生向往型语言”，也就是说可以用这类美好的语言去说动对方进行某事；凡是那些遵循、效仿、涉及上述阴类事物的说辞，可以叫作“人生忌讳型语言”，也就是说可以用这类令人厌恶的语言去威胁、警醒对方中止某种计谋。游说中运用捭阖之术时，先用阴言和阳言去试探对方（以确定对方是喜欢阴言还是喜欢阳言）。由此，与喜欢阳言的人论谈时，以使用涉及上述阳类事物的崇高语言为主；与喜欢阴言的人论谈时，以使用涉及上述阴类事物的卑下语言为主。这样，我们就可以用卑下的阴言去打动小人，用崇高的阳言去说服君子。照此而论，用捭阖之术去游说，就没有探测不出来的真情，就没有不听从我们决策的人，就没有不能说服的对象。用捭阖之术去游说，可以说动每个普通民众，可以说动每个有封地的大夫，可以说动每个诸侯国的国王，甚至可以说动天下的君主。若要成就小事，可以小到极限，没有更小的了；若要成就大事，可以大到极限，没有更大的了。")]),v._v(" "),_("Badge",{attrs:{text:"阅读感悟",type:"warning"}}),v._v(" "),_("p",[v._v("在合作方面，可以用约束规则来促进共同目标，也可以用共同目标促进约束规则。在存在方面，存在的阴阳两面是能量的均衡，是动态平衡的状态。有天赋也要有自我保护机制，所缺也可转化为所盈，符合当下存在状态即可。捭阖可以是保护自己边界的方法论也可以是了解他人品质的方法论。人的认知作用实践。实践决定认知。")]),v._v(" "),_("p",[_("strong",[v._v("四")])]),v._v(" "),_("p",[v._v("益损、去就、倍反，皆以阴阳御其事[1]。阳动而行，阴止而藏；阳动而出，阴隐而入。阳还终阴[2]，阴极反阳。以阳动者，德相生也；以阴静者，形相成也[3]。以阳求阴，苞以德也；以阴结阳，施以力也[4]；阴阳相求，由捭阖也。此天地阴阳之道，而说人之法也，为万事之先，是谓圆方之门户[5]。")]),v._v(" "),_("br"),v._v(" "),_("Badge",{attrs:{text:"注释",type:"warning"}}),v._v(" "),_("p",[v._v("[1]御：治理，处理，掌控。")]),v._v(" "),_("p",[v._v("[2]还：还返，再生。")]),v._v(" "),_("p",[v._v("[3]德：内在本质，自身规律。形：外在形态。")]),v._v(" "),_("p",[v._v("[4]苞：包容，规范。结：连接，引申为辅助。施以力：施以外力，由外影响内。")]),v._v(" "),_("p",[v._v("[5]先：先导，这里指既定法则。圆方：即天地，古人认为天圆地方，故以“圆方”代指天地。")]),v._v(" "),_("Badge",{attrs:{text:"译文",type:"warning"}}),v._v(" "),_("p",[v._v("所有的裨益或损害、离去与接近、背叛和复归，都是阴阳之道的行为表现，可用阴阳之道加以掌控和驾驭。阳以动为特征，故主要表现为进取；阴以静止为特征，故主要表现为闭藏。阳动必然显现出来，阴止必然潜藏进去。阳发展到极致就成为阴，阴超过了极限就变为阳。用阳去拨动事物，是为了让它按照自身规律发展；用阴去安定事物，是为了让它巩固自己的形态。用阳去统括阴，就要用内部规律去规范外在形态；用阴去辅佐阳，就要用外在形态去影响内在本质。阴阳相辅相成，互为其用，集中体现在捭阖之术上。这就是世间万物阴阳变化的基本规律，也是游说人主所应遵循的根本原则，是万事万物生成变化的既定法则，也即所谓的天地万物运行的关键。")]),v._v(" "),_("Badge",{attrs:{text:"阅读感悟",type:"warning"}}),v._v(" "),_("p",[v._v("存在本身是阴阳互补之态，发展阳态到极致，会触发反者道之动，存在的锋芒影响其他存在的稳态，会被毁灭。发展发展阴态到极致，会直接触动存在根基，刺激存在进入迭代，走向毁灭或者升级。阴阳互补调和，存在可以更加稳定温和发展。")]),v._v(" "),_("p",[v._v("以史为鉴")]),v._v(" "),_("p",[v._v("司马熹巧施连环捭阖计")]),v._v(" "),_("p",[v._v("战国时期，中山国国王的妃子阴姬和江姬都很受宠，两人都想做王后，故经常明争暗斗。纵横策士司马熹见有机可趁，便暗中派人去游说阴姬：“做王后的事可得重视！一旦争到手，那可就是一人之下、万人之上，要风得风、要雨得雨了；争不到手，不但自己有性命之忧，还会祸延九族，早晚被得势者灭之而后甘！若想稳操胜券，最好去找司马熹出主意。”阴姬闻言，忙请司马熹献策，并许以重金酬谢。司马熹应承下来之后，便一步步施展开其精心谋划的连环套式“阴阳捭阉术”。")]),v._v(" "),_("p",[v._v("他先去拜见中山王，自告奋勇说要去邻国走走，借机刺探对方消息，再回来谋划强国之策。中山王自然高兴万分，下令给他备上礼物让他先去赵国。")]),v._v(" "),_("p",[v._v("司马熹见过赵王，在闲谈中故意说道：“早闻贵国出美人，可我转了几天，还真没见到有哪一位超过我国那位阴姬的。”赵王闻听此言，顿时来了兴趣，忙问究竟美到什么程度，司马熹便添油加醋、绘声绘色地向赵王描述道：“美目盼兮，巧笑倩兮，芙蓉如面柳如眉，有倾国倾城之姿、沉鱼落雁之貌！”赵王听了恨不得马上收入自己宫中，忙问司马熹：“有无良策将之献于本王？”司马熹故意顿了一下，近前悄声说：“她是我们大王的宠妃，我怎敢妄言？请大王忘了这话吧，否则传扬出去，小的脑袋不保啊！”赵王冷笑一声，下定决心非弄到手不可。")]),v._v(" "),_("p",[v._v("司马熹见此行目的已达到，忙收拾行装回到了中山国，且立即进宫向国王报告：“赵王昏庸透顶，又残暴至极，只知攻攻杀杀；又沉迷酒色，荒淫无道。我已得到可靠消息，说赵王看中了阴姬，正想方设法要将之纳入宫中！”“岂有此理！”中山王一听，勃然大怒，“竟如此肆意妄为，简直是欺人太甚！”司马熹故作急切地安抚道：“请息怒，大王！目前赵国比我们强大，我们能打得过他们吗？若赵王硬来索取，不给吧，打起来有亡国之危；给吧，大王您又会被天下人耻笑说堂堂一国之君连自己的妃子都保护不了……”")]),v._v(" "),_("p",[v._v("“那你说该如何处理？”中山王何尝不明白形势，又气又急之下，便不耐烦地打断司马熹的话头，向他征求意见。司马熹见国王已六神无主，钻入自己套中，不由得心中窃喜，但仍假装稍稍思考了一下，才凑近前说道：“我想到一个办法可以打消赵王的这个念头。不如大王即刻将阴姬册封为王后，让赵王死心。当今天下还没有谁敢公然索要别人的王后做妻子的，即使国家再强大也不敢冒天下之大不韪！否则，必将引起列国公愤，就算真的开战，友邦也会出兵帮助我们的。”“好！就这么办！”中山王闻言如释重负，马上传令册封阴姬为王后。赵王知道后，果然也死了心。阴姬对司马熹千恩万谢，自然也给了他不少好处。")]),v._v(" "),_("p",[v._v("之所以称司马熹此计为“连环捭阖计”，是基于他在阴姬、中山王和赵王这三方人物之间多方周旋，纵横捭阖。无论是面对这三人中的哪一个，司马熹都能因人而异、适时适当地有所“开启”，有所“闭藏”，该说什么、说多少，用“阴言”还是用“阳言”……他都胸有成竹、进退自如，使事情朝着自己预期的方向发展，最终达到自己的目的。")]),v._v(" "),_("p",[v._v("范雎欲扬先抑说秦王")]),v._v(" "),_("p",[v._v("范雎本是战国时期魏国中大夫须贾的门客，他才华出众，能言善辩，到处游说。后来因遭人嫉恨，几乎让相国魏齐毒打至死，幸而被他用计逃脱，在其好友郑安平的帮助下，改名为张禄隐匿了起来。在这之后，恰值秦国派来出使魏国的使臣王稽很欣赏他的才干，范雎才得以随他进入秦国。")]),v._v(" "),_("p",[v._v("范雎到秦国后，居住了一年多，并未得到秦昭王的重用，无非是粗茶淡饭地招待，备受冷落。作为身怀奇韬伟略的雄辩之士，范雎并不心急，每日里深居简出，闭门读书，潜心钻研天下大事和诸侯纷争的复杂形势，等待机会“不鸣则已，一鸣惊人”。")]),v._v(" "),_("p",[v._v("当时的秦国，虽有外忧，但内患的处理更迫在眉睫。秦国有号称“四贵”的四大家族，四贵之中，以相国魏冉（穰侯）为首，他是当朝宣太后的异父兄弟，同宣太后的另一弟弟华阴君以及宣太后的另外两个儿子一起，倚仗着宣太后的势力聚敛财富，以致私家的财富比王室还多。而且魏冉贪得无厌，为了扩大自己的封地——陶邑，便想跨越韩、魏两国去攻打齐国的寿张、刚县，因为这两个地方离陶邑很近，打下来后秦王又不方便分封给别人，其结果只能是扩大自己的封地。")]),v._v(" "),_("p",[v._v("范雎得知这一讯息后，便趁机上书给秦昭王：“大王在上：臣听说英明的君王执政，有功者必予以赏赐，有才者必给予官爵；功劳大的俸禄优厚，功劳多的爵位尊贵，能力强的官职显赫。所以无才能者，不敢随便就职；有才能者，也不会埋没他的才干。大王可以算得上是一个英明的君王了，因此，臣才敢斗胆进言。假如您认为臣的话有道理，乞望大王能够推行；假如您认为臣的话不合适，那么臣留在这里也无济于事，只好打点行装离开了。常言道：‘昏君奖赏他所喜爱的人，而惩罚他所憎恶的人；而明君就不是这样，奖赏一定要加给有功的人，刑罚一定要判给有罪的人。’现在臣的胸膛抵挡不住砧板，臣的腰部也承受不了斧钺，臣又怎敢把自己的进言当作儿戏呢？”")]),v._v(" "),_("p",[v._v("细想范雎这番话，无非是为了说明自己的进言是出之有据、慎之又慎的，而绝不是不负责任的信口雌黄。借此来引起秦昭王的重视。这还不够，范雎接着又借物自喻和借题发挥，使秦昭王从内心深处觉得要想解除内患，就必须任用一些能人。最后他强调道：“话说得深了，臣不敢写在信上；说得浅了，览之无余味，也没多大意思。出于种种考虑，臣乞求大王能否稍微抽出一丁点儿游猎观赏的闲暇时间，使臣能有一个面见大王亲自进言的机会。”就这样，他绕了半天的圈子，卖了半天的关子，还是没有给秦昭王出一点实际的主意。不料秦昭王读了他的上书颇感兴趣、大为欣赏，于是便派人向范雎道歉，并请他立即进宫面圣，想听听这位魏国来的客人到底有什么奇谋妙策。")]),v._v(" "),_("p",[v._v("进宫之前，其实早已有人告知范雎秦昭王将要在离宫接见他，可他却一副呆头呆脑的样子，装作什么都不懂似的往宫内走去。宫中值勤的宦官一见，连忙大声喊住他：“回来，秦王在离宫！”范雎故意愣了一下，假装迷糊地反问道：“秦国还有个秦王吗？不是只有太后和穰侯吗？”宦官一听这话，大惊失色，面面相觑，不知所措。只因范雎此言一针见血，正好击中了秦昭王的要害。秦昭王听了宦官们的汇报，明白了范雎是话中有话。于是，他赶忙亲自迎接范雎入宫，态度非常谦恭。")]),v._v(" "),_("p",[v._v("秦昭王把范雎迎入内宫后，喝令左右的人退下，只剩下他俩。秦昭王直起腰腿，跪身（古人席地而坐，两膝着地，臀部坐在两足跟上，跪身就是在坐势的基础上，臀部离开两足跟，把身子挺直了以示庄重尊敬）请求说：“先生打算怎样来教导寡人呢？”范雎只是“啊，啊”了两声。过了一会儿，秦昭王再次请求，范雎还是“啊，啊”了两声。如此这般一连三次，秦昭王未免有点失望，只好问道：“先生看来是不愿意教诲寡人了。”范雎拿够了架子，这才开口拜谢道：“岂敢？岂敢？臣不远千里来投奔大王，就是为了能有机会向大献计献策的。臣只是觉得，作为一个客居他乡的异国人，和大王的交情还不深，然而臣所进言的，都是希望能够帮助大王合适地治理好国家，处理好君臣、父子之间的关系。臣是愿意向大王献上自己一片愚昧的忠心，但是又不知道大王此刻心里能不能听进去、愿不愿听从，这就是大王问了三次而臣不敢马上回答的缘故。”范雎说到这里，稍微停顿了一下。秦昭王鼓励他道：“先生的道德学识是寡人难以企及的，不过，寡人看先生似乎有点担心祸从口出，请先生务必放心，尽管直言，寡人是不会怪罪先生的。”")]),v._v(" "),_("p",[v._v("范雎这才舒畅地继续进言道：“臣并不是因为有所畏惧而不敢说，臣很清楚，臣今天在大王面前说了一些过分的话，也许明天就会招来杀身之祸。但臣不想苟且偷生，大王如果听从了为臣的进言，那么死对臣来说，就微不足道了。死，是任何人都无法逃避的。臣如果现在能够对秦国的统一有点好处，得报大王的知遇之恩，就是明天去赴刑场又有什么可怕的呢？”范雎的这番话，与其说是想给秦昭王一个他已将生死置之度外的印象，不如说是他以此来表示自己进言的重要性及迫切性。接下来，他似乎还不急着把话引入正题，又继续举了伍子胥、箕子等人的例子，说明了忠臣不怕死以及不赞成有才不外露的做法。而且接着又提到：“臣所担心的是，万一臣由于向大王进言而招杀身之祸，从此天下的有识之士引以为戒，便都不肯投奔、归顺和效力于秦国，那才是秦国的最大悲哀呢！”")]),v._v(" "),_("p",[v._v("秦昭王闻言若有所思，点头称是。范雎见状，方才试探着说道：“大王现在对上畏惧太后的威严，对下又迷惑于奸臣的伪诈，居住在深宫里面，离不开保傅（辅导天子和诸侯子弟的官员）的照料，终生受到迷惑，分不清忠良与奸臣，这样，久而久之，重则连宗庙也保不住，轻则会使自己陷入孤立的危境，这就是臣所担心的。至于穷困潦倒，遭受侮辱甚至死亡，臣都无所畏惧。如果臣的死能够换来秦国的强大与安宁，那么，这种死不是比活着更有价值吗？”范雎的这番慷慨陈辞，大大打动了秦昭王，他激动地抓住范雎的手，对他说道：“先生这是说的哪里话！秦国是个远离中原的边远国度，加之寡人又愚昧无能，先生来到这里，这是上天要使寡人得到先生的辅助，而使祖先宗庙里的香火不致熄灭。寡人今天能坐在这里聆听先生的教诲，这是上天偏爱寡人的祖先而不抛弃他老人家的后代啊！从今以后，事无大小，上至太后，下至大臣，先生均可评说。希望先生把您所知道的一切都详尽地教导给寡人，不要再怀疑寡人的诚意了。”")]),v._v(" "),_("p",[v._v("范雎听罢，舒了一口气，赶紧对秦昭王拜了一拜，秦昭王见了，也立即还礼回拜。至此，范雎见秦昭王已完全被自己说服了，这才开始了自己的长篇大论，话题从外交到内政，最后还谈到如何肃清宣太后和以穰侯为首的四大家族势力。从此，范雎完全得到秦昭王的信赖，得以借助秦国这个辉煌的历史舞台逐步展开了他心中一系列的宏图大略。")]),v._v(" "),_("p",[v._v("西汉著名大学者刘向在其《说苑》一书的《善说》篇里，辑录了鬼谷子的一段话，将之译成白话文便是：“在他人不喜欢你的时候去纠正他，是很难的。劝说行不通，论理不听从，那是你论辩的道理不清楚；道理已经明辩却仍然行不通的，那是因为你没有顽强地去坚持；已经顽强地坚持了却还是行不通的，那是因为你没有切合他心中的喜好。明辩道理，说理清楚，坚持它，巩固它，又能适合被游说之人的喜好，你的言辞就会变得神奇而珍贵，清楚而分明，就能进入对方的心中。像这样游说还不成功的，天下间还未曾听说过。这样的游说就叫做善说了。”所以，对待被游说者要做到说理透彻，投其所好。因此，捭阖之术首先就要让对方将自己的实力和底细全部暴露出来，然后再决定是否为他出谋划策，实施游说。这样，才可以说人、说家，甚至可以说国、说天下了。而上述的范雎说秦昭王无疑是一个典型的成功范例，我们可以从中得到不少的启发，进而能有效地指导自己的实践。")]),v._v(" "),_("p",[v._v("薛宣软硬兼施惩县令")]),v._v(" "),_("p",[v._v("薛宣，字赣君，是汉成帝时知名的大臣。在他担任左冯翊期间，其所管辖的高陵县令杨湛、栎阳县令谢游都是贪婪狡猾、妄自尊大之徒。只是由于他们掌握着一县的大权，虽然以前的郡守都曾经多次想对他们的违法乱纪行为予以追究，但苦于无凭无据，最终都不了了之。")]),v._v(" "),_("p",[v._v("等到薛宣走马上任，杨、谢二人立刻到府衙拜见。薛宣也当即设置酒饭，热情周到地招待他们。")]),v._v(" "),_("p",[v._v("与此同时，薛宣也一直暗中搜寻他们的犯罪事实，经过努力调查，终于获得了他们受贿勒索的全部证据。")]),v._v(" "),_("p",[v._v("薛宣观察到杨湛似乎有改正错误之意，也颇尊敬自己，尚能听从劝告，于是他便亲手写了一封信，将杨湛所犯的罪行一一列举出来，随后把信私底下交给他，并告诉杨湛：“你手下的县吏与百姓检举揭发你的罪状，我已在这封信上一条条地陈列出来了，还有人状告你犯了中饱私囊的‘主守盗’之罪。我敬重作为一县长官的你，又顾念到一旦东窗事发你将受到法律的重罚，不忍心把你的事情张扬出去，所以秘密地写了这封信告诉你，希望你能够明白进退，妥善地处理这些事情，以便今后能重新清白为官。如果你确实没有干过这些不法之事，那么就重新将这封信封好再交还给我，我一定会为你申明冤屈，还君清誉。”")]),v._v(" "),_("p",[v._v("杨湛知道信上所列的都与自己所犯的罪行一致，但见薛宣措辞语气皆温润有加，并无意加害于己，便立刻解下了县令的印绶，交给县吏，并写了一封信感谢薛宣，未曾有半句怨言。")]),v._v(" "),_("p",[v._v("而那位栎阳县令谢游却自以为是大儒，颇有名声，认为薛宣也一样拿自己没办法，所以根本就看不起薛宣。")]),v._v(" "),_("p",[v._v("薛宣对谢游的傲慢态度一清二楚，当即发出正式公文，对他进行公开的指责，公文中这样写道：“告栎阳令：你手下的县吏和百姓告发你治理县政细琐苛刻，随意贬罚吏民，被罚做苦差的竟高达千人以上；用不正当的手段聚敛钱财数十万，供私自大兴土木之用；又听任富吏隐瞒、操纵物品价格。以上所有事情已经全部调查清楚，我本来想派遣官吏前来审讯此案，但又怕辜负了当初推荐你的人，以致给儒士们带来耻辱，所以暂时停止你的县令职务。孔子有云：‘陈力就列，不能者止。’希望你能多多反思。”")]),v._v(" "),_("p",[v._v("谢游见到公文后，只得灰溜溜地辞官而去了。")]),v._v(" "),_("p",[v._v("“阴阳相求”，软硬兼施，就是说要针对不同的对象，具体问题具体分析，从而采取不同的惩治方法。因高陵县令杨湛已有悔过之心，所以薛宣顺水推舟，双方心照不宣，让他在自己的罪状前悔过，不露声色地处理好了这方面的问题。而栎阳县令谢游非但无悔过之心，而且还不把薛宣放在眼里，所以薛宣以硬对硬，将罪证扔给他，公然免去了他的官职。就这样，薛宣软硬兼施，一拉一打，捭阖之术运用的力度可谓恰到好处。")]),v._v(" "),_("p",[v._v("现代活用")]),v._v(" "),_("p",[v._v("【商界】")]),v._v(" "),_("p",[v._v("“扮猪吃老虎”的日本人")]),v._v(" "),_("p",[v._v("有一次，日本一家公司与美国的一家公司正进行一场许可证贸易方面的谈判。")]),v._v(" "),_("p",[v._v("谈判一开始，美方代表就滔滔不绝、天花乱坠地向日方介绍情况，而日方代表则一言不发，只是认真倾听、埋头记录。当美方代表讲完后征求日方的意见时，日方代表却“迷惘”地表示“听不明白”，只是要求“回去认真研究一下”。")]),v._v(" "),_("p",[v._v("几星期后，当日方出现在第二轮的谈判桌前时已是全新的阵容，由于他们一再声称“不了解情况”，美方代表只好又重复地介绍了一次，日方代表却仍是埋头记录，以“还不明白”为由使谈判不得不暂告休会。")]),v._v(" "),_("p",[v._v("到了第三轮谈判，日方代表又再次易将换兵，并以此为理由故伎重演，只是告诉对方：回去后一旦有了结果，便会立即通知对方。")]),v._v(" "),_("p",[v._v("就这样半年多过去了，正当美方代表团因得不到日方任何回音而烦躁不安、破口大骂日方毫无诚意时，日方突然派了一个由董事长亲自率领的代表团飞抵美国，在美国人毫无准备的情况下要求立即开始谈判，并向美方抛出最后方案，以迅雷不及掩耳之势，催逼美国人进一步讨论细节问题。措手不及的美方代表终于不得不同日本人达成了一个明显有利于日方的协议。")]),v._v(" "),_("p",[v._v("事后，美方这次谈判的首席代表无限感慨地说道：“这次谈判，是继日本在偷袭珍珠港之后获得的又一重大胜利！”")]),v._v(" "),_("p",[v._v("熟练运用善于防御、勇于进攻的有捭有阖之道是制胜的法宝。所以，在商业谈判中，面对来势汹汹的对手时，我们要注意避其锋芒，乘其疲惫之际，突然出击，以打败对方。")]),v._v(" "),_("p",[v._v("在这个案例中，聪明的日方多听少说，装聋作哑，在谈判伊始就采取消极防御即“阖”的策略；等敌人急躁疲倦、濒于无望之际，再一举采取“捭”的策略——积极进攻，杀了对方一个漂亮的“回马枪”，扮猪吃老虎，最终获得了谈判的成功。这也正如维克多·金姆在《大胆下注》中所说的那样：“你应该少说为妙。我确信，如果你说得愈少，而对方说得愈多，那么你在谈判中就愈容易取得战功。”")]),v._v(" "),_("p",[v._v("【职场】")]),v._v(" "),_("p",[v._v("背叛者，请走开")]),v._v(" "),_("p",[v._v("在竞争异常激烈的现代商业社会中，作为一个大型高技术公司的分部经理，随时都会面临各种难题，肯尼斯现在就处于这种让人煎熬的境地：都快六个月了，销售额一直在下跌，他的上司为了提高肯尼斯负责的这个部门的销售额，不断给他施加压力。一个多月以来，他一直在热切地期待着可以寻找到一位能给他们带来希望、且有丰富经验的销售人员以增强其部门的销售力量。但直到三天前，他才总算遇到了一位很有希望的人选。")]),v._v(" "),_("p",[v._v("从那个人自信地走进他的办公室的那一刻起，肯尼斯就异常强烈地感觉到这正是他要找的人。随着会谈的深入，他越来越激动了，甚至觉得这真是天赐良机，使他有幸遇到了这个人。此人不仅有杰出的营销经验，而且了解肯尼斯行业的来龙去脉，最让人感兴趣的是，这人刚从一个他为之成功奋斗了六年的公司里辞去了一份重要的职务，而他辞职的那个公司恰恰就是肯尼斯所在公司的主要竞争对手。")]),v._v(" "),_("p",[v._v("通过整个会谈，肯尼斯深深地意识到，无论从哪方面来讲，这位销售人员都远远优于他已会见过的其他申请者。正当他打定主意要雇佣那人（再打一两个电话核实一下他的情况）时，那人却有些诡秘地从其随身携带的公文包里摸出一个小方信封，并从中抽出一张计算机磁盘，像握着无价之宝似的拿在手里。")]),v._v(" "),_("p",[v._v("“您能猜出这张盘上存的是什么吗？”他面带狡黠地问肯尼斯。")]),v._v(" "),_("p",[v._v("肯尼斯摇摇头。")]),v._v(" "),_("p",[v._v("那人仍然微笑着，声音中透出些许自恃，他继续向肯尼斯解释说，这张盘里存有有关肯尼斯所在公司的竞争对手——也即他原来所任职的那家公司的大量机密信息，其中就包括其顾客的详细资料以及肯尼斯的公司正在参与竞争的一项重要投标项目的投资数据等。在会见结束时，那人向肯尼斯信誓旦旦地许诺，如果肯尼斯雇佣他，这张盘就属于肯尼斯的了，另外他还将提供更多类似的信息。")]),v._v(" "),_("p",[v._v("在那人转身离开自己的办公室时，肯尼斯心中突然涌起了一种强烈的反应：愤怒。这家伙怎么能做出这种事情？肯尼斯明白，那人的建议与给予是不对的，就冲这一点，这个家伙就不是肯尼斯想要的那种人。")]),v._v(" "),_("p",[v._v("后来，肯尼斯直接打电话给那个销售人员，告诉他即使从能力上讲他也许是最适合这个位置的人，但自己还是不准备雇佣他。")]),v._v(" "),_("p",[v._v("鬼谷子告诉过我们：用人之道，贵在识人，利用捭阖之术让对方开启，使对方无所顾忌、侃侃而谈，致使我们能够更多地掌握对方的情况，并以此来决定取舍。所谓“口者，心之门户也；心者，神之主也。志意、喜欲、思虑、智谋，此皆由门户出入，故关之以捭阖，制之以出入”。因此，在上例中，肯尼斯运用捭阖之术，反复鉴定，静待对方将自己的实力或者心中的算计全部暴露出来，进而为自己作出正确的评估与决定提供了充足的佐证。")]),v._v(" "),_("p",[v._v("处世")]),v._v(" "),_("p",[v._v("不拒绝“自己的东西”")]),v._v(" "),_("p",[v._v("威尔森是专门为一家花样设计室推销草图的推销员，而他的工作对象则主要是那些服装设计师和纺织品制造商。这段时间内，一连三个月，他每个礼拜都去拜访纽约一位著名的服装设计师。威尔森不止一次地对朋友诉苦道：“他从来不会拒绝我，每次接见我也都表现得很热情，可是他也从来不买我推销的那些图纸。他总是很有礼貌地跟我谈话，而且还很仔细地看我带去的东西，可是到了最后总是那句话：‘威尔森，我看我们是做不成这笔生意了。’”")]),v._v(" "),_("p",[v._v("就这样经过屡战屡败、屡败屡战，威尔森终于总结出了经验：原来是因为自己太遵循那老一套的推销方法了，每次一见到客户就拿出自己的图纸，滔滔不绝地说开了，讲它的构思、创意，新奇在何处，该用到什么地方……客户都听得烦了，绝大多数都是出于礼貌才忍耐着听他说完的。威尔森认识到这种方法确实已经太落后了，迫切需要改进。于是他下定决心，每个星期都抽出一些时间去看处世方面的书，思考为人处世的哲学。")]),v._v(" "),_("p",[v._v("过了不多久，他还真想出了对付那位难缠的服装设计师的方法。他了解到那位服装设计师其实比较自负，别人设计的东西他大多看不上眼。于是威尔森便绘了几张尚未完成的设计草图来到这位设计师的办公室，诚恳地问道：“鲍勃先生，如果你愿意的话，能否帮我一个小忙？”同时恭敬地递上那几份准备好的草图，对服装设计师说：“这里有几张我们尚未完成的草图，能否请你不吝赐教，指点我们应该如何把它们完成才能对你更有用处呢？”对方闻言接过图纸仔细地看了看，发现设计人的初衷很有创意，就答复道：“威尔森，你把这些图纸留在这里让我看看吧。”")]),v._v(" "),_("p",[v._v("几天过去了，威尔森再次来到他的办公室，服装设计师对这几张图纸提出了一些建议。威尔森用笔记了下来，然后回去按照其意思很快就把草图完成了。结果是服装设计师再次看后大为满意，全部接受了。")]),v._v(" "),_("p",[v._v("从那之后，威尔森总是记得征求这位买主的意见，然后根据他的意见制作图纸。这位买主非常满意，连续订购了许多图纸，威尔森也从中赚取了不少的佣金。")]),v._v(" "),_("p",[v._v("“我现在才算彻底明白了，为什么以前那么多天都投资进去了我还不能和他做成买卖，”威尔森恍然大悟地说，“我以前总是不停地催促他快买，说这对他有用、那对他有好处而他总是不以为然，不是说这不合适，就是说那不新颖。现在我只是按照他的意思去做，而他也由此觉得这就是他自己创造的，满足了他的心理需求——自我表现欲。因为他不能拒绝‘他自己的’东西，这就变成了他要而不是我勉强推销了，工作起来自然就容易多了。”")]),v._v(" "),_("p",[v._v("所以，对于推销员来说，应该把顾客推到台前，而自己则隐身幕后。如果把产品和顾客自身的感受联系在一起，就能让他们更乐于接受，采用这种手段无疑会让事情进展得更顺利，业绩也就随之大大提高了。同样的道理，在为人处世方面，很多时候也应如此，要想“达人心之理，见变化之朕焉，而守司其门户”，我们不妨“或开而示之，或阖而闭之。开而示之者，同其情也；阖而闭之者，异其诚也。可与不可，审明其计谋，以原其同异。离合有守，先从其志”。这样顺着别人的思路来，先顺其意后观其变，渐渐演化为促成与对方合作的一个前提和推动力量，往往能让交往无阻无碍，办事顺顺利利。")])],1)}),[],!1,null,null,null);_.default=e.exports}}]);